ainpage.php">Panel</a><a class="active" href="showclinic.php">Klinikler</a></nav></div></header><main class="admin-wrap"><div class="page-head"><div><span class="eyebrow">KLİNİK YÖNETİMİ</span><h1>Klinikler</h1><p>Sistemde kayıtlı kliniklerin güncel listesini görüntüleyin.</p></div><a class="button" href="addclinic.php">+ Klinik Ekle</a></div><section class="card table-card"><div class="table-top"><h2>Klinik listesi</h2><span class="count"><?php echo $count;?> klinik</span></div><?php if(!$count):?><div class="empty">Kayıtlı klinik bulunmuyor.</div><?php else:?><div class="table-wrap"><table class="data-table"><thead><tr><th>CID</th><th>Klinik</th><th>Adres</th><th>İlçe</th><th>Şehir</th><th>Telefon</th><th>Manager</th></tr></thead><tbody><?php while($r=mysqli_fetch_assoc($result)):?><tr><td>#<?php echo (int)$r['CID'];?></td><td class="clinic-name"><?php echo htmlspecialchars($r['Name']);?></td><td class="muted"><?php echo htmlspecialchars($r['Address']);?></td><td><?php echo htmlspecialchars($r['Town']);?></td><td><?php echo htmlspecialchars($r['City']);?></td><td><?php echo htmlspecialchars($r['Contact']);?></td><td><?php echo htmlspecialchars($r['mid']?:'-');?></td></tr><?php endwhile;?></tbody></table></div><div class="mobile-list"><?php mysqli_data_seek($result,0);while($r=mysqli_fetch_assoc($result)):?><article class="mobile-item"><div class="mobile-name"><?php echo htmlspecialchars($r['Name']);?></div><div class="mobile-grid"><div><strong>ID</strong>#<?php echo (int)$r['CID'];?></div><div><strong>Konum</strong><?php echo htmlspecialchars($r['Town']);?> / <?php echo htmlspecialchars($r['City']);?></div><div><strong>Telefon</strong><?php echo htmlspecialchars($r['Contact']);?></div><div><strong>Manager</strong><?php echo htmlspecialchars($r['mid']?:'-');?></div></div></article><?php endwhile;?></div><?php endif;?></section></main></body></html>